87:     public static async Task<RomInfo> VerifyRomAsync(string path, IProgress<(double Progress, string Status)>? progress = null, CancellationToken ct = default)
88:     {
89:         if (!File.Exists(path))
90:             return new RomInfo(path, "Unknown", "", false);
91: 
92:         var fileInfo = new FileInfo(path);
93:         long totalBytes = fileInfo.Length;
94:         if (totalBytes == 0)
95:             return new RomInfo(path, "Unknown", "", false);
96: 
97:         using var sha1 = SHA1.Create();
98:         await using var stream = File.OpenRead(path);
99:         byte[] buffer = new byte[1024 * 1024]; // 1MB chunks
100:         long readBytes = 0;
101:         int bytesRead;
102: 
103:         while ((bytesRead = await stream.ReadAsync(buffer.AsMemory(0, buffer.Length), ct)) > 0)
104:         {
105:             sha1.TransformBlock(buffer, 0, bytesRead, null, 0);
106:             readBytes += bytesRead;
107:             var pct = ((double)readBytes / totalBytes) * 100.0;
108:             progress?.Report((pct, $"Verifying cartridge ROM... {pct:0}%"));
109:         }
110: 
111:         sha1.TransformFinalBlock(buffer, 0, 0);
112:         var hashHex = Convert.ToHexString(sha1.Hash ?? Array.Empty<byte>()).ToLowerInvariant();
113: 
114:         if (hashHex == CleanUsaSha1)
115:             return new RomInfo(path, "USA (NA)", hashHex, true);
116:         if (hashHex == CleanEuSha1)
117:             return new RomInfo(path, "Europe (EU)", hashHex, true);
118: 
119:         return new RomInfo(path, "Unsupported / Modified", hashHex, false);
120:     }
