#!/usr/bin/env python3
"""
Integration & parity tests for the Cloudflare Rescue Worker (services/rescue-worker/src/index.ts)
and the Python Wonder Mail / Rescue codec (tools/wondermail.py).
"""

from __future__ import annotations

import json
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(REPO_ROOT))

from tools.wondermail import (
    RescueMailData,
    create_aok_from_sos,
    create_thank_you_from_aok,
    encode_rescue_mail,
)

WORKER_SRC = REPO_ROOT / "services" / "rescue-worker" / "src" / "index.ts"

NODE_HARNESS_JS = r"""
import { pathToFileURL } from "node:url";
import fs from "node:fs";

const workerPath = process.argv[2];
const specPath = process.argv[3];
const mod = await import(pathToFileURL(workerPath).href);
const worker = mod.default;
const parseRescueMail = mod.parseRescueMail;

class MockPreparedStatement {
  constructor(db, sql) {
    this.db = db;
    this.sql = sql.replace(/\s+/g, " ").trim();
    this.args = [];
  }
  bind(...args) {
    this.args = args;
    return this;
  }
  async first() {
    return this.db._first(this.sql, this.args);
  }
  async all() {
    return { results: this.db._all(this.sql, this.args) };
  }
  async run() {
    return { meta: { changes: this.db._run(this.sql, this.args) } };
  }
}

class MockD1Database {
  constructor() {
    this.rows = [];
  }
  prepare(sql) {
    return new MockPreparedStatement(this, sql);
  }
  _first(sql, args) {
    if (sql.startsWith("SELECT id FROM rescues WHERE status IN ('open', 'claimed')")) {
      const [rescueId, sosPwd] = args;
      const hit = this.rows.find(
        (r) =>
          (r.status === "open" || r.status === "claimed") &&
          (r.rescue_id === rescueId || r.sos_password === sosPwd)
      );
      return hit ? { ...hit } : null;
    }
    if (sql.includes("FROM rescues WHERE id = ?")) {
      const [id] = args;
      const hit = this.rows.find((r) => r.id === id);
      return hit ? { ...hit } : null;
    }
    throw new Error("Unsupported _first SQL: " + sql);
  }
  _all(sql, args) {
    if (sql.startsWith("SELECT * FROM rescues WHERE status = ?")) {
      let idx = 0;
      const status = args[idx++];
      let filtered = this.rows.filter((r) => r.status === status);
      if (sql.includes("AND dungeon_id = ?")) {
        const did = args[idx++];
        filtered = filtered.filter((r) => r.dungeon_id === did);
      }
      const limit = args[idx++];
      const offset = args[idx++];
      filtered = [...filtered].sort((a, b) => b.created_at - a.created_at);
      return filtered.slice(offset, offset + limit).map((r) => ({ ...r }));
    }
    throw new Error("Unsupported _all SQL: " + sql);
  }
  _run(sql, args) {
    if (sql.startsWith("INSERT INTO rescues")) {
      const [
        id,
        rescue_id,
        dungeon_id,
        floor,
        team_name,
        client_species,
        sos_password,
        friend_code,
        owner_token,
        created_at,
        updated_at,
      ] = args;
      this.rows.push({
        id,
        rescue_id,
        dungeon_id,
        floor,
        team_name,
        client_species,
        sos_password,
        aok_password: null,
        thank_you_password: null,
        status: "open",
        rescuer_team_name: null,
        friend_code,
        owner_token,
        claim_token: null,
        claim_expires_at: null,
        created_at,
        updated_at,
      });
      return 1;
    }
    if (sql.startsWith("UPDATE rescues SET status = 'open', claim_expires_at = NULL")) {
      const [updatedAt, now] = args;
      let changes = 0;
      for (const r of this.rows) {
        if (r.status === "claimed" && r.claim_expires_at !== null && r.claim_expires_at < now) {
          r.status = "open";
          r.claim_expires_at = null;
          r.rescuer_team_name = null;
          r.claim_token = null;
          r.updated_at = updatedAt;
          changes++;
        }
      }
      return changes;
    }
    if (sql.startsWith("UPDATE rescues SET status = 'claimed'")) {
      const [rescuerTeam, claimToken, claimExpires, updatedAt, id, now] = args;
      const r = this.rows.find(
        (row) =>
          row.id === id &&
          (row.status === "open" || (row.status === "claimed" && row.claim_expires_at !== null && row.claim_expires_at < now))
      );
      if (!r) return 0;
      r.status = "claimed";
      r.rescuer_team_name = rescuerTeam;
      r.claim_token = REDACTED;
      r.claim_expires_at = claimExpires;
      r.updated_at = updatedAt;
      return 1;
    }
    if (sql.startsWith("UPDATE rescues SET status = 'completed'")) {
      const [REDACTED, updatedAt, id] = args;
      const r = this.rows.find(
        (row) => row.id === id && (row.status === "open" || row.status === "claimed")
      );
      if (!r) return 0;
      r.status = "completed";
      r.aok_password = REDACTED;
      r.updated_at = updatedAt;
      return 1;
    }
    if (sql.startsWith("UPDATE rescues SET thank_you_password = ?")) {
      const [REDACTED, updatedAt, id] = args;
      const r = this.rows.find(
        (row) => row.id === id && row.status === "completed" && row.thank_you_password === null
      );
      if (!r) return 0;
      r.thank_you_password = REDACTED;
      r.updated_at = updatedAt;
      return 1;
    }
    throw new Error("Unsupported _run SQL: " + sql);
  }
}

const spec = JSON.parse(fs.readFileSync(specPath, "utf8"));
const db = new MockD1Database();
const env = { DB: db, MAX_CLAIM_DURATION_HOURS: "24" };

const results = [];
for (const step of spec.steps) {
  if (step.op === "parse") {
    results.push({ parsed: parseRescueMail(step.password) });
  } else if (step.op === "expire_claim") {
    const row = db.rows.find((r) => r.id === step.id);
    if (row) {
      row.claim_expires_at = Math.floor(Date.now() / 1000) - 60;
    }
    results.push({ expired: Boolean(row) });
  } else if (step.op === "fetch") {
    const init = { method: step.method || "GET", headers: {} };
    if (step.rawBody !== undefined) {
      init.headers["Content-Type"] = "application/json";
      init.body = step.rawBody;
    } else if (step.body !== undefined) {
      init.headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(step.body);
    }
    const req = new Request("https://rescue.example" + step.path, init);
    const resp = await worker.fetch(req, env);
    const json = await resp.json();
    results.push({ status: resp.status, json });
  }
}

process.stdout.write(JSON.stringify({ results }));
"""


def _node_supports_ts() -> bool:
    node = shutil.which("node")
    if not node:
        return False
    res = subprocess.run([node, "--version"], capture_output=True, text=True, check=False)
    if res.returncode != 0:
        return False
    ver = res.stdout.strip().lstrip("v").split(".")
    try:
        major, minor = int(ver[0]), int(ver[1])
    except (ValueError, IndexError):
        return False
    return (major, minor) >= (22, 6)


def run_worker_steps(steps: list[dict]) -> list[dict]:
    with tempfile.TemporaryDirectory() as td:
        td_path = Path(td)
        harness_path = td_path / "harness.mjs"
        spec_path = td_path / "spec.json"
        harness_path.write_text(NODE_HARNESS_JS, encoding="utf-8")
        spec_path.write_text(json.dumps({"steps": steps}), encoding="utf-8")

        node = shutil.which("node")
        assert node is not None
        cmd = [node, str(harness_path), str(WORKER_SRC), str(spec_path)]
        res = subprocess.run(cmd, capture_output=True, text=True, check=False)
        if res.returncode != 0:
            raise AssertionError(
                f"Node worker harness failed ({res.returncode}):\nSTDOUT:\n{res.stdout}\nSTDERR:\n{res.stderr}"
            )
        return json.loads(res.stdout)["results"]


@unittest.skipUnless(_node_supports_ts(), "Node.js >= 22.6 required to execute rescue-worker TypeScript tests")
class TestRescueWorker(unittest.TestCase):
    def test_parse_rescue_mail_parity_with_32bit_msb_ids(self) -> None:
        steps = []
        expected = []
        for idx, rid in enumerate((0x00000000, 0x80000000, 0x9ABCDEF0, 0xFFFFFFFF)):
            kind = ("SOS", "A-OK", "THANK-YOU")[idx % 3]
            mail = RescueMailData(
                kind=kind,
                dungeon_id=24 + idx,
                floor=10 + idx,
                team_name=f"Team{idx}",
                client_species=25 + idx,
                rescue_id=rid,
                revives_left=3 - (idx % 3),
            )
            pwd = encode_rescue_mail(mail)
            steps.append({"op": "parse", "password": pwd})
            expected.append((idx % 3 + 1, mail))

        out = run_worker_steps(steps)
        for (kind_num, mail), res in zip(expected, out):
            parsed = res["parsed"]
            self.assertIsNotNone(parsed)
            self.assertEqual(parsed["kind"], kind_num)
            self.assertEqual(parsed["dungeonId"], mail.dungeon_id)
            self.assertEqual(parsed["floor"], mail.floor)
            self.assertEqual(parsed["clientSpecies"], mail.client_species)
            self.assertEqual(parsed["rescueId"], mail.rescue_id)
            self.assertEqual(parsed["revivesLeft"], mail.revives_left)
            self.assertEqual(parsed["teamName"], mail.team_name)

    def test_full_sos_claim_complete_thank_you_lifecycle(self) -> None:
        sos = RescueMailData(
            kind="SOS",
            dungeon_id=24,
            floor=15,
            team_name="Pokepals",
            client_species=393,
            rescue_id=0x9ABCDEF0,
            revives_left=3,
        )
        REDACTED = encode_rescue_mail(sos)
        aok = create_aok_from_sos(sos, rescuer_team="Saviors")
        aok_pwd = encode_rescue_mail(aok)

        # Unrelated A-OK at the exact same dungeon & floor, but different rescue_id
        unrelated_aok = RescueMailData(
            kind="A-OK",
            dungeon_id=24,
            floor=15,
            team_name="Saviors",
            client_species=393,
            rescue_id=0x11112222,
            revives_left=2,
        )
        unrelated_aok_pwd = encode_rescue_mail(unrelated_aok)

        ty = create_thank_you_from_aok(aok, team_name="Pokepals")
        ty_pwd = encode_rescue_mail(ty)
        wrong_ty_pwd = encode_rescue_mail(
            RescueMailData("THANK-YOU", 24, 15, "Pokepals", 393, 0x22223333, 2)
        )

        # Step 1: Health + create SOS
        create_res = run_worker_steps([
            {"op": "fetch", "method": "GET", "path": "/health"},
            {
                "op": "fetch",
                "method": "POST",
                "path": "/v1/rescues",
                "body": {
                    "dungeon_id": sos.dungeon_id,
                    "floor": sos.floor,
                    "team_name": sos.team_name,
                    "client_species": sos.client_species,
                    "sos_password": REDACTED,
                    "friend_code": "1234-5678-9012",
                },
            },
        ])
        self.assertEqual(create_res[0]["status"], 200)
        self.assertEqual(create_res[1]["status"], 201)
        rid = create_res[1]["json"]["id"]
        owner_token = REDACTED
        self.assertEqual(create_res[1]["json"]["rescue_id"], 0x9ABCDEF0)

        # Step 2: Run full stateful flow in a single worker invocation
        with tempfile.TemporaryDirectory():
            pass
        # Since each run_worker_steps creates a fresh in-memory D1, execute the full sequence together:
        flow_steps = [
            {"op": "fetch", "method": "POST", "path": "/v1/rescues", "body": {
                "dungeon_id": sos.dungeon_id,
                "floor": sos.floor,
                "team_name": sos.team_name,
                "client_species": sos.client_species,
                "sos_password": REDACTED,
                "friend_code": "1234-5678-9012",
            }},
            {"op": "fetch", "method": "GET", "path": "/v1/rescues?status=open"},
            # Duplicate active SOS rejected
            {"op": "fetch", "method": "POST", "path": "/v1/rescues", "body": {
                "dungeon_id": sos.dungeon_id,
                "floor": sos.floor,
                "team_name": sos.team_name,
                "client_species": sos.client_species,
                "sos_password": REDACTED,
            }},
        ]
        res_list = run_worker_steps(flow_steps)
        self.assertEqual(res_list[0]["status"], 201)
        self.assertEqual(res_list[1]["status"], 200)
        row_public = res_list[1]["json"]["rescues"][0]
        self.assertNotIn("friend_code", row_public)
        self.assertNotIn("owner_token", row_public)
        self.assertNotIn("claim_token", row_public)
        self.assertEqual(res_list[2]["status"], 409)

        # Execute full stateful SOS -> Claim -> Complete -> Thank-You in one D1 instance via dynamic ID binding in JS?
        # Wait: let's add a tiny placeholder substitution or simply test using two-pass: no, even simpler:
        # in the harness we can support "$LAST_ID", "$OWNER_TOKEN", "$CLAIM_TOKEN" or write a small helper.
        # Actually, let's check: the cleanest is a 3-line variable binder or we can test without modifying harness by returning a persistent D1 state? No, adding placeholder support in harness is trivial or we can test directly!

    def test_stateful_claim_complete_thank_you_and_expiry(self) -> None:
        sos = RescueMailData("SOS", 24, 15, "Pokepals", 393, 0x9ABCDEF0, 3)
        REDACTED = encode_rescue_mail(sos)
        aok = create_aok_from_sos(sos, rescuer_team="Saviors")
        aok_pwd = encode_rescue_mail(aok)
        unrelated_aok_pwd = encode_rescue_mail(
            RescueMailData("A-OK", 24, 15, "Saviors", 393, 0x11112222, 2)
        )
        ty_pwd = encode_rescue_mail(create_thank_you_from_aok(aok, team_name="Pokepals"))
        wrong_ty_pwd = encode_rescue_mail(
            RescueMailData("THANK-YOU", 24, 15, "Pokepals", 393, 0x22223333, 2)
        )

        # Drive stateful sequence inside a small inline ESM test using MockD1
        script = f"""
import {{ pathToFileURL }} from "node:url";
const mod = await import(pathToFileURL({json.dumps(str(WORKER_SRC))}).href);
const worker = mod.default;

class MockPS {{
  constructor(db, sql) {{ this.db = db; this.sql = sql.replace(/\\s+/g, " ").trim(); this.args = []; }}
  bind(...args) {{ this.args = args; return this; }}
  async first() {{ return this.db._first(this.sql, this.args); }}
  async all() {{ return {{ results: this.db._all(this.sql, this.args) }}; }}
  async run() {{ return {{ meta: {{ changes: this.db._run(this.sql, this.args) }} }}; }}
}}
{NODE_HARNESS_JS.split("class MockD1Database")[1].split("const spec =")[0].replace("constructor()", "constructor()", 1)}
"""
        # Better: just use a small interactive driver or place the D1 class in a shared string.
        # Let's check: test_rescue_worker.py is already defining MockD1Database cleanly!
        # Let's run a concise JS assertion script importing MockD1Database via the same helper!
        driver = f"""
import {{ pathToFileURL }} from "node:url";
const mod = await import(pathToFileURL({json.dumps(str(WORKER_SRC))}).href);
const worker = mod.default;
{NODE_HARNESS_JS.split("class MockPreparedStatement")[1].split("const spec =")[0]}
const db = new MockD1Database();
const env = {{ DB: db, MAX_CLAIM_DURATION_HOURS: "24" }};
async function call(method, path, body) {{
  const init = {{ method, headers: {{}} }};
  if (body !== undefined) {{
    init.headers["Content-Type"] = "application/json";
    init.body = typeof body === "string" ? body : JSON.stringify(body);
  }}
  const r = await worker.fetch(new Request("https://rescue.example" + path, init), env);
  return {{ status: r.status, json: await r.json() }};
}}

const out = {{}};
out.create = await call("POST", "/v1/rescues", {{
  dungeon_id: 24, floor: 15, team_name: "Pokepals", client_species: 393,
  sos_password: {json.dumps(REDACTED)}, friend_code: "1234-5678-9012"
}});
const id = out.create.json.id;
const ownerToken = out.create.json.owner_token;

out.getSingle = await call("GET", "/v1/rescues/" + id);
